/* Demonstrates using statfs() to retrieve and print filesystem statistics */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/vfs.h> /* Required for struct statfs and statfs() */

int main(int argc, char *argv[]) {
    struct statfs fs_stats;
    const char *target_path = (argc > 1) ? argv[1] : "/";

    printf("Querying filesystem stats for path: %s\n", target_path);

    if (statfs(target_path, &fs_stats) == -1) {
        fprintf(stderr, "Error calling statfs on %s: %s (errno %d)\n", 
                target_path, strerror(errno), errno);
        return EXIT_FAILURE;
    }

    // Output key statistics. Note: Types often require casting (e.g., unsigned long long).
    printf("--- Filesystem Statistics ---\n");
    printf("Optimal Block Size (f_bsize): %lu bytes\n", 
           (unsigned long)fs_stats.f_bsize);
    printf("Total Data Blocks (f_blocks): %llu\n", 
           (unsigned long long)fs_stats.f_blocks);
    printf("Free Blocks (f_bfree): %llu\n", 
           (unsigned long long)fs_stats.f_bfree);
    printf("Available Blocks (unprivileged) (f_bavail): %llu\n", 
           (unsigned long long)fs_stats.f_bavail);
    printf("Maximum Filename Length (f_namelen): %lu\n", 
           (unsigned long)fs_stats.f_namelen);

    return EXIT_SUCCESS;
}
